declare_lint ! { # [doc = " The `invalid_atomic_ordering` lint detects passing an `Ordering`"] # [doc = " to an atomic operation that does not support that ordering."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " # use core::sync::atomic::{AtomicU8, Ordering};"] # [doc = " let atom = AtomicU8::new(0);"] # [doc = " let value = atom.load(Ordering::Release);"] # [doc = " # let _ = value;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Some atomic operations are only supported for a subset of the"] # [doc = " `atomic::Ordering` variants. Passing an unsupported variant will cause"] # [doc = " an unconditional panic at runtime, which is detected by this lint."] # [doc = ""] # [doc = " This lint will trigger in the following cases: (where `AtomicType` is an"] # [doc = " atomic type from `core::sync::atomic`, such as `AtomicBool`,"] # [doc = " `AtomicPtr`, `AtomicUsize`, or any of the other integer atomics)."] # [doc = ""] # [doc = " - Passing `Ordering::Acquire` or `Ordering::AcqRel` to"] # [doc = "   `AtomicType::store`."] # [doc = ""] # [doc = " - Passing `Ordering::Release` or `Ordering::AcqRel` to"] # [doc = "   `AtomicType::load`."] # [doc = ""] # [doc = " - Passing `Ordering::Relaxed` to `core::sync::atomic::fence` or"] # [doc = "   `core::sync::atomic::compiler_fence`."] # [doc = ""] # [doc = " - Passing `Ordering::Release` or `Ordering::AcqRel` as the failure"] # [doc = "   ordering for any of `AtomicType::compare_exchange`,"] # [doc = "   `AtomicType::compare_exchange_weak`, `AtomicType::update`, or"] # [doc = "   `AtomicType::try_update`."] INVALID_ATOMIC_ORDERING , Deny , "usage of invalid atomic ordering in atomic operations and memory fences" }